import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """
    Approach: marginal-cost-partition multicast with a globally-chosen shared
    trunk. Several candidate trunk structures are built and the one with the
    smallest union edge cost is committed to the paid ledger on partition 0:
      A) the incumbent's undirected-collapsed Steiner tree (dsts whose tree
         path lacks directed edges fall back to their Dijkstra path);
      B) a pruned arborescence: union of per-dst directed Dijkstra trees with
         non-terminal leaves iteratively removed;
      C) a directed metric-closure Steiner arborescence: complete graph on
         {src}+terminals weighted by directed shortest-path distances, MST
         rooted at src, each MST edge expanded into its real directed shortest
         path, then pruned. Fully directed, so no per-dst fallback dilutes
         the sharing (fixes candidate A's reverse-orientation weakness).
    Partitions 1..n-1 then re-route with the marginal ledger: among <=10
    shortest simple paths pick min (marginal cost, hop count). Reusing the
    committed path has marginal 0, so later partitions can never add a new
    edge to the union — they may only ride already-paid trunks. Per-dst
    Dijkstra fallback keeps unreachable dsts valid. Bounded compute: one
    Steiner tree, |dsts|+2 Dijkstras, one MST, <=10 simple paths per re-route.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # Directed view with None costs treated as free.
    W = nx.DiGraph()
    for u, v, data in h.edges(data=True):
        c = data.get("cost")
        W.add_edge(u, v, cost=0.0 if c is None else c)

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    inf = float("inf")

    def dijkstra_route(dst):
        """Fallback: cheapest per-dst path emitted on all partitions."""
        try:
            path = nx.dijkstra_path(W, src, dst, weight="cost")
        except (nx.NetworkXException, ValueError):
            return False
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            for j in range(bc_topology.num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, h[s][t]])
        return True

    # Per-dst directed shortest paths and costs.
    dij_path = {}
    for dst in dsts:
        try:
            dij_path[dst] = nx.dijkstra_path(W, src, dst, weight="cost")
        except (nx.NetworkXException, ValueError):
            pass

    reachable = [d for d in dsts if d in dij_path]

    def finalize(routes_partial):
        """Complete route dict with Dijkstra fallback; return (routes, union cost)."""
        routes = {}
        for d in dsts:
            if d in routes_partial:
                routes[d] = routes_partial[d]
            elif d in dij_path:
                routes[d] = dij_path[d]
        used, cost = set(), 0.0
        for p in routes.values():
            for a, b in zip(p, p[1:]):
                if (a, b) not in used:
                    used.add((a, b))
                    cost += W[a][b]["cost"]
        return routes, cost

    def bfs_paths(T):
        """Paths from src to every node reachable in arborescence T."""
        parent = {src: None}
        q = [src]
        while q:
            u = q.pop(0)
            for w in T.neighbors(u):
                if w not in parent:
                    parent[w] = u
                    q.append(w)
        paths = {}
        for n in parent:
            if n == src:
                continue
            chain, cur = [], n
            while cur is not None:
                chain.append(cur)
                cur = parent[cur]
            paths[n] = list(reversed(chain))
        return paths

    def prune_tree(T, keep):
        """Iteratively drop non-terminal sinks (nothing downstream of them)."""
        T = T.copy()
        changed = True
        while changed:
            changed = False
            for n in list(T.nodes):
                if n != src and n not in keep and T.out_degree(n) == 0:
                    T.remove_node(n)
                    changed = True
        return T

    # ---- Candidate A: incumbent undirected-collapsed Steiner tree.
    S = nx.Graph()
    for u, v, data in W.edges(data=True):
        if not S.has_edge(u, v) or W[u][v]["cost"] < S[u][v]["cost"]:
            S.add_edge(u, v, cost=W[u][v]["cost"])
    best_routes, best_cost = finalize({})
    if reachable:
        tree = None
        try:
            tree = nx.algorithms.approximation.steinertree.steiner_tree(
                S, [src] + reachable, weight="cost"
            )
        except (nx.NetworkXException, ValueError):
            tree = None
        if tree is not None:
            tp = {src: [src]}
            q = [src]
            while q:
                u = q.pop(0)
                for w in tree.neighbors(u):
                    if w not in tp:
                        tp[w] = tp[u] + [w]
                        q.append(w)
            partial = {}
            for d in reachable:
                p = tp.get(d)
                if p is not None and all(
                    W.has_edge(a, b) for a, b in zip(p, p[1:])
                ):
                    partial[d] = p
            rA, cA = finalize(partial)
            if cA < best_cost:
                best_routes, best_cost = rA, cA

        # ---- Candidate B: pruned union of per-dst Dijkstra trees.
        TB = nx.DiGraph()
        for d in reachable:
            p = dij_path[d]
            for a, b in zip(p, p[1:]):
                TB.add_edge(a, b)
        TB = prune_tree(TB, set(reachable))
        pb = bfs_paths(TB)
        rB, cB = finalize({d: pb[d] for d in reachable if d in pb})
        if cB < best_cost:
            best_routes, best_cost = rB, cB

        # ---- Candidate C: directed metric-closure Steiner arborescence.
        nodes = [src] + sorted(reachable)
        dist, sp = {}, {}
        for u in nodes:
            try:
                dl, pl = nx.single_source_dijkstra(W, u, weight="cost")
                dist[u], sp[u] = dl, pl
            except nx.NetworkXException:
                dist[u], sp[u] = {}, {}
        Cg = nx.Graph()
        for i, u in enumerate(nodes):
            for v in nodes[i + 1:]:
                d = min(dist[u].get(v, inf), dist[v].get(u, inf))
                if d < inf:
                    Cg.add_edge(u, v, weight=d)
        if len(nodes) > 1 and nx.is_connected(Cg):
            mst = nx.minimum_spanning_tree(Cg)
            parent = {src: None}
            q = [src]
            while q:
                u = q.pop(0)
                for w in mst.neighbors(u):
                    if w not in parent:
                        parent[w] = u
                        q.append(w)
            if all(t in parent for t in reachable):
                TC = nx.DiGraph()
                expandable = True
                for child, par in parent.items():
                    if par is None:
                        continue
                    p = sp[par].get(child)
                    if p is None:
                        expandable = False
                        break
                    for a, b in zip(p, p[1:]):
                        TC.add_edge(a, b)
                if expandable:
                    TC = prune_tree(TC, set(reachable))
                    pc = bfs_paths(TC)
                    rC, cC = finalize(
                        {d: pc[d] for d in reachable if d in pc}
                    )
                    if cC < best_cost:
                        best_routes, best_cost = rC, cC

    # ---- Partition 0: commit the globally-chosen trunk to the ledger.
    paid = {}

    def emit(path, j, dst):
        for a, b in zip(path, path[1:]):
            paid[(a, b)] = paid.get((a, b), 0.0) + W[a][b]["cost"]
            bc_topology.append_dst_partition_path(dst, j, [a, b, h[a][b]])

    fallback = set()
    for d in dsts:
        r = best_routes.get(d)
        if r is None:
            dijkstra_route(d)
            fallback.add(d)
        else:
            emit(r, 0, d)

    # ---- Partitions 1..n-1: marginal-ledger re-route (reuse = marginal 0).
    for d in dsts:
        if d in fallback or d not in best_routes:
            continue
        base = best_routes[d]
        for j in range(1, bc_topology.num_partitions):
            best_key, best_path = (0.0, len(base)), base
            try:
                for idx, path in enumerate(
                    nx.shortest_simple_paths(W, src, d, weight="cost")
                ):
                    if idx >= 10:
                        break
                    m = sum(
                        W[a][b]["cost"]
                        for a, b in zip(path, path[1:])
                        if (a, b) not in paid
                    )
                    key = (m, len(path))
                    if key < best_key:
                        best_key, best_path = key, path
            except (nx.NetworkXException, ValueError):
                pass
            emit(best_path, j, d)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


